{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 41,
      "verse": 3,
      "text_ar": "أجساد البشر- أقول لك يا شيث، (أنت) رجل الله، لا تبكِ ولا تصلِّ وتضرع لأجل زيت شجرة الرحمة لتمسح به أباك آدم لأجل أوجاع جسده."
    },
    {
      "chapter": 42,
      "verse": 1,
      "text_ar": "«لأني أقول لك إنك لن تستطيع البتة أن تنال منه شيئاً إلا في الأيام الأخيرة»."
    },
    {
      "chapter": 42,
      "verse": 2,
      "text_ar": "[وعندما تتم خمسة آلاف وخمسمائة سنة، حينئذ سيأتي إلى الأرض الملك المحبوب جداً المسيح، ابن الله، ليحيي جسد آدم ومعهم ليحيي"
    },
    {
      "chapter": 42,
      "verse": 3,
      "text_ar": "أجساد الأموات. وهو نفسه، ابن الله، عندما يأتي سيعتمد في نهر الأردن، وعندما يخرج من ماء الأردن، فحينئذ سيمسح من"
    },
    {
      "chapter": 42,
      "verse": 4,
      "text_ar": "زيت الرحمة كل من يؤمن به. ويكون زيت الرحمة جيلاً بعد جيل لأولئك المستعدين ليولَدوا ثانية من"
    }
  ]
}
